function instanceChoices(){const slot=change.elements.slot.value,parts=current?.[slot]||[];if(change.elements.instance){const previous=change.elements.instance.value;change.elements.instance.innerHTML=parts.length?parts.map((part,index)=>`<option value="${index}">${index+1}. ${esc(displayName(part))}</option>`).join(''):'<option value="0">No existing item selected</option>';change.elements.instance.value=Number(previous)<parts.length?previous:'0'}if(change.elements.mode){if(!multiple.has(slot))change.elements.mode.value='replace';const add=[...(change.elements.mode.options||[])].find(option=>option.value==='add');if(add)add.disabled=!multiple.has(slot)}}
