function candidate(){requireCurrent();const slot=change.elements.slot.value,part=records.find(row=>row.id===change.elements.replacement.value&&row.cat===slot);if(!part||part.builderEligible===false)throw Error('Choose an exact replacement model.');const next=copy(current),mode=change.elements.mode?.value==='add'?'add':'replace',index=Number(change.elements.instance?.value||0);if(mode==='add'){if(!multiple.has(slot))throw Error('This category supports one selected item in this upgrade plan.');next[slot].push(part)}else{if(!Number.isInteger(index)||index<0||index>=Math.max(1,next[slot].length))throw Error('Choose an existing item to replace.');if(next[slot].length)next[slot][index]=part;else next[slot]=[part]}if(count(next)>99)throw Error('An upgrade plan supports up to 99 component instances.');return{slot,p:part,next,index,mode}}
function validateParts(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw)||Object.keys(raw).some(slot=>!slots.includes(slot)))throw Error('The inventory contains an unsupported component category.');const parsed={};for(const slot of slots){const values=raw[slot]===undefined?[]:raw[slot];if(!Array.isArray(values)||values.length>99||values.some(id=>!idOK(id)))throw Error('The inventory contains an invalid component reference.');parsed[slot]=values.map(id=>{const part=records.find(row=>row.id===id&&row.cat===slot);if(!part)throw Error('A saved component is missing or in the wrong category: '+id+'. Confirm it manually before importing.');return part})}if(count(parsed)>99)throw Error('An upgrade plan supports up to 99 component instances.');return parsed}
