function renderExtras(){const target=$('[data-upgrade-extra-parts]');if(!target)return;const carried=slots.flatMap(slot=>inventoryExtras[slot].map((part,index)=>({slot,part,index})));target.innerHTML=`<details><summary>Additional components${carried.length?' · '+carried.length+' recorded':''}</summary><p>Record extra memory kits, drives, graphics cards or fans. Quantities remain separate; compatibility still needs review.</p><ul>${carried.map(({slot,part,index})=>`<li>${esc(slotLabels[slot])}: ${esc(displayName(part))} <button type="button" class="button secondary" data-upgrade-remove-extra="${slot}" data-extra-index="${index}">Remove</button></li>`).join('')}</ul><div class="program-form"><label>Category<select data-upgrade-extra-slot>${[...multiple].map(slot=>`<option value="${slot}">${esc(slotLabels[slot])}</option>`).join('')}</select></label><label>Exact existing model<select data-upgrade-extra-model></select></label><button type="button" class="button secondary" data-upgrade-add-extra>Add existing item</button></div></details>`;const category=target.querySelector('[data-upgrade-extra-slot]'),model=target.querySelector('[data-upgrade-extra-model]');const choices=()=>{if(!category||!model)return;model.innerHTML='<option value="">Choose a model</option>'+records.filter(part=>part.builderEligible!==false&&part.cat===category.value).map(part=>`<option value="${esc(part.id)}">${esc(displayName(part))}</option>`).join('')};category?.addEventListener('change',choices);choices();target.querySelector('[data-upgrade-add-extra]')?.addEventListener('click',()=>{const part=records.find(row=>row.id===model?.value&&row.cat===category?.value);if(!part||!multiple.has(part.cat))return status('Choose an exact model for the additional item.');if(count(selections())>=99)return status('An upgrade plan supports up to 99 component instances.');if(!form.elements[part.cat].value)form.elements[part.cat].value=part.id;else inventoryExtras[part.cat].push(part);invalidate();form.dispatchEvent(new Event('change',{bubbles:true}));renderExtras();status('Existing item recorded. Create the reuse plan to recheck the whole inventory.')});for(const button of target.querySelectorAll?.('[data-upgrade-remove-extra]')||[])button.addEventListener('click',()=>{const slot=button.dataset.upgradeRemoveExtra,index=Number(button.dataset.extraIndex);if(!slots.includes(slot)||!Number.isInteger(index)||index<0)return;inventoryExtras[slot].splice(index,1);invalidate();form.dispatchEvent(new Event('change',{bubbles:true}));renderExtras();status('Additional item removed from the entered inventory. Create the reuse plan again.')})}
function loadOwnedContext(){const params=new URL(location.href).searchParams,packed=params.get('inventory')||params.get('build'),legacy=params.get('owned');if(!packed&&!legacy)return;try{let raw=Object.fromEntries(slots.map(slot=>[slot,[]]));if(packed){if(packed.length>12000)throw Error('The shared inventory is too large.');const groups=packed.split(',');if(groups.length<8||groups.length>slots.length)throw Error('The shared inventory uses an unsupported slot layout.');for(let index=0;index<groups.length;index++)raw[slots[index]]=groups[index]?groups[index].split('~'):[]}else{const values=legacy.split(/[~,]/);if(values.length>99||values.some(id=>!idOK(id)))throw Error('The shared inventory is invalid.');for(const id of values){const part=records.find(row=>row.id===id&&slots.includes(row.cat));if(!part)throw Error('The shared inventory contains an unknown component.');raw[part.cat].push(id)}}applyInventory(validateParts(raw));status('Exact selections carried into the inventory, including additional instances. Confirm what is installed, then create the reuse plan.')}catch(error){status(error.message+' Select your exact installed parts manually.')}}
function createPlan(start,parts,restoredPhases=[]){baseline=copy(start);current=copy(parts);phases=restoredPhases;inventoryDirty=false;const out=$('[data-upgrade-result]');$('[data-upgrade-phases]').replaceChildren();if(!count(current)){current=null;document.dispatchEvent?.(new Event('pcp:upgrade-plan'));out.innerHTML='<h2>Start with the PC you have.</h2><p>Record at least one installed part, then create a reuse plan. Unselected categories have not been checked.</p>';$('[data-upgrade-change-result]').innerHTML='';status('Choose a current component to begin. No compatibility checks have run.');return}const rows=slots.filter(slot=>current[slot].length).map(slot=>`<tr><th scope="row">${esc(slotLabels[slot]||slot)}</th><td>${current[slot].map(part=>`<a href="/learn/${esc(part.id)}.html">${esc(displayName(part))}</a>`).join('<br>')}</td><td>Keep unless workload evidence justifies a change; verify support for a swap.</td></tr>`).join('');out.innerHTML=`<h2>Keep, replace or verify</h2><p>Doing nothing is a valid option. Comparable workload measurements are needed before claiming an upgrade gain.</p><div class="table-scroll"><table class="program-table"><caption>Your confirmed starting inventory</caption><thead><tr><th scope="col">Part</th><th scope="col">Exact selection</th><th scope="col">Decision basis</th></tr></thead><tbody>${rows}</tbody></table></div><p><strong>New spending is unknown.</strong> Existing-part value is not a new purchase. Obtain complete quotes before comparing an upgrade with a platform replacement.</p><div data-upgrade-readiness></div>`;const report=renderChecks(current,$('[data-upgrade-readiness]'));const symptom=form.elements.symptom.value;if(symptom!=='none')out.insertAdjacentHTML('afterbegin',`<p class="program-note">Start with <a href="/troubleshooting/?symptom=${esc(symptom)}">safe checks for your symptom</a>. A configuration fix may avoid a purchase.</p>`);for(const [index,phase]of phases.entries()){const node=document.createElement('section');node.className='program-match';node.innerHTML=`<h3>Imported phase ${index+1}</h3><div></div>`;renderChecks(validateParts(phase.parts),node.querySelector('div'));$('[data-upgrade-phases]').append(node)}instanceChoices();document.dispatchEvent?.(new Event('pcp:upgrade-plan'));status('Reuse plan created; '+(report.counts['needs-verification']||0)+' checks need evidence.');window.PCP_EVENTS?.track('upgrade_result_generated',{page_type:'upgrade',category:form.elements.goal.value})}
window.PCP_UPGRADE={snapshot:()=>current?{parts:ids(current),baseline:ids(baseline),region:form.elements.region.value,ready:!inventoryDirty}:null,catalog:()=>records,inventory:()=>loaded?ids(selections()):null,applyConfirmedInventory:(raw,expected)=>{if(!loaded)throw Error('Wait for part choices to load before replacing inventory.');const before=selections();if(typeof expected!=='string'||expected.length>20000||JSON.stringify(ids(before))!==expected)throw Error('Your inventory changed during this review. Review the pasted list again before replacing it.');const parts=validateParts(raw);if(!count(parts))throw Error('An empty pasted list cannot clear your existing inventory.');if(slots.some(slot=>!multiple.has(slot)&&parts[slot].length>1))throw Error('Resolve duplicate processor, motherboard, power supply, case or CPU-cooler selections first.');try{applyInventory(parts)}catch(error){applyInventory(before);throw error}invalidate();form.dispatchEvent(new Event('change',{bubbles:true}));try{window.PCP_EVENTS?.track('parts_list_imported',{page_type:'upgrade',action:'confirmed'})}catch{}return{parts:ids(parts)}}};
fetch('/data/program-parts.json').then(response=>{if(!response.ok)throw Error('Part choices could not load.');return response.json()}).then(data=>{if(!Array.isArray(data)||data.length>5000||data.some(part=>!part||!idOK(part.id)||typeof part.name!=='string'||!part.name.trim()||typeof part.brand!=='string'||!slots.includes(part.cat))||new Set(data.map(part=>part.id)).size!==data.length)throw Error('Part choices have an invalid or duplicate identity.');records=data;loaded=true;for(const slot of slots){if(!form.elements[slot])throw Error('This component form needs the current update. Reload the page.');form.elements[slot].innerHTML='<option value="">Not selected / unknown</option>'+records.filter(part=>part.builderEligible!==false&&part.cat===slot).map(part=>`<option value="${esc(part.id)}">${esc(displayName(part))}</option>`).join('');form.elements[slot].disabled=false}replacementChoices();renderExtras();loadOwnedContext();$('[data-upgrade-loading]').textContent='Select exact installed parts. Older parts remain available; age alone is not a reason to replace them.'}).catch(error=>{loaded=false;$('[data-upgrade-loading]').textContent=error.message+' Use the hardware catalog or retry the page.';status(error.message)});
if(globalThis.PCP_PARTS_IMPORT)globalThis.PCP_PARTS_IMPORT.attach({form:parse,target:$('[data-upgrade-matches]'),upgrade:window.PCP_UPGRADE,document,status});else parse.addEventListener('submit',event=>{event.preventDefault();$('[data-upgrade-matches]').textContent='Pasted-list review could not load. Reload this page, or select exact installed models below. Your inventory was not changed.'});
form.addEventListener('submit',event=>{event.preventDefault();if(!loaded)return status('Part choices are still unavailable.');const parts=selections();createPlan(parts,parts)});
