change.addEventListener('submit',event=>{event.preventDefault();try{const choice=candidate(),target=$('[data-upgrade-change-result]');renderChecks(choice.next,target);target.insertAdjacentHTML('afterbegin',`<h3>Alternative: ${esc(choice.p.name)}</h3><p>${choice.mode==='add'?'Add this item':'Replace the selected item'} and preserve the other component instances. Compare required support, cooling, connectors and complete costs. This selection does not establish a measured uplift.</p>`);status('Alternative checked without changing the current phase.')}catch(error){status(error.message)}});
$('[data-upgrade-phase]').addEventListener('click',()=>{try{if(phases.length>=25)throw Error('Export or start a new plan before adding more than 25 phases.');const choice=candidate();current=choice.next;const report=rules.createReadiness({parts:current});phases.push({slot:choice.slot,productId:choice.p.id,index:choice.index,mode:choice.mode,parts:ids(current),checks:report.checks});const node=document.createElement('section');node.className='program-match';node.innerHTML=`<h3>Phase ${phases.length}: ${choice.mode==='add'?'add':'replace'} ${esc(slotLabels[choice.slot]||choice.slot)} ${esc(choice.p.name)}</h3><div></div>`;renderChecks(current,node.querySelector('div'));renderChecks(current,$('[data-upgrade-readiness]'));$('[data-upgrade-phases]').append(node);instanceChoices();status('Phase saved to this open plan. Export to keep it. '+report.counts.failed+' documented conflicts; '+(report.counts['needs-verification']||0)+' checks need evidence.')}catch(error){status(error.message)}});
$('[data-upgrade-builder]').addEventListener('click',()=>{try{requireCurrent();const owned=slots.flatMap(slot=>[...new Set(current[slot].map(part=>part.id))].filter(id=>current[slot].filter(part=>part.id===id).length<=baseline[slot].filter(part=>part.id===id).length)),revision=rules.normalizeRevision({parts:current,owned,region:form.elements.region.value,budget:form.elements.budget.value,requirements:{workload:['gaming','creator'].includes(form.elements.goal.value)?form.elements.goal.value:'general'}},records).revision,url=new URL(rules.buildURL(revision,location.origin));location.href=url.pathname+url.search}catch(error){status(error.message)}});
$('[data-upgrade-export]').addEventListener('click',()=>{try{requireCurrent();const data={schema:'pcp-upgrade-v1',region:form.elements.region.value,currency:form.elements.region.value==='US'?'USD':'CAD',budget:rules.validAmount(form.elements.budget.value),baseline:ids(baseline),parts:ids(current),rulesVersion:rules.VERSION,phases:phases.map(phase=>({slot:phase.slot,productId:phase.productId,index:phase.index,mode:phase.mode,parts:phase.parts})),limitations:['Manual confirmed inventory; exact support, quantities and clearances still need verification.','No measured uplift or complete checked cost is available.']},blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='pc-upgrade-plan.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500);status('Plan exported with exact quantities and phases. Private workload notes are not included.');window.PCP_EVENTS?.track('upgrade_export',{page_type:'upgrade'})}catch(error){status(error.message)}});
$('[data-upgrade-import]')?.addEventListener('change',async event=>{const input=event.currentTarget,file=input.files?.[0];if(!file)return;try{if(!loaded)throw Error('Wait for part choices to load.');if(file.size>131072)throw Error('Use a plan file smaller than 128 KB.');const data=JSON.parse(await file.text());if(!data||data.schema!=='pcp-upgrade-v1'||!['CA','US'].includes(data.region)||!Array.isArray(data.phases)||data.phases.length>25)throw Error('Use an exported PC Part Performance upgrade plan.');const start=validateParts(data.baseline),parts=validateParts(data.parts),importedPhases=data.phases.map(phase=>{if(!phase||!slots.includes(phase.slot)||!idOK(phase.productId))throw Error('An upgrade phase has an invalid identity.');const selected=validateParts(phase.parts);if(!selected[phase.slot].some(part=>part.id===phase.productId))throw Error('A phase component does not match its selected parts.');return{slot:phase.slot,productId:phase.productId,parts:ids(selected),checks:rules.createReadiness({parts:selected}).checks}});form.elements.region.value=data.region;form.elements.budget.value=rules.validAmount(data.budget)??'';applyInventory(parts);createPlan(start,parts,importedPhases);status('Upgrade plan imported. Every phase was rechecked using current catalog evidence; private notes were not imported.')}catch(error){status(error.message+' Existing saved builder revisions were not changed.')}finally{input.value=''}});
